package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertAll;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

/** A metadata-capable cursor still batches statement reads when a range truncates the run being counted. */
class LmdbPrefixRunPartialBatchWorkTest {

	private static final int NEIGHBORS_PER_PREDICATE = 512;
	private static final long FIRST_NEIGHBOR = 10_000;

	@ParameterizedTest(name = "order={0}, boundary={1}")
	@CsvSource({ "spoc,lower", "spoc,upper", "opsc,lower", "opsc,upper" })
	void partialNodeRunsKeepBulkReadsWithoutPrefetchingCompleteMetadataRuns(String order, String boundary)
			throws Exception {
		int nodeField = order.charAt(0) == 's' ? TripleIndex.SUBJ_IDX : TripleIndex.OBJ_IDX;
		TripleIndex index = new TripleIndex(order, order, false, 0, 0, (txn, name, flags) -> -1);
		LmdbPrefixRunPlan plan = new LmdbPrefixRunPlan(index, new int[] { nodeField }, 1);
		CountingRows rows = new CountingRows(order);
		long[] metadataCalls = { 0 };
		int partialRows = NEIGHBORS_PER_PREDICATE + NEIGHBORS_PER_PREDICATE / 2;
		try (LmdbPrefixRunCursor cursor = new LmdbPrefixRunIterator(plan, rows, -1, -1, -1, -1, true,
				quad -> {
					assertThat(quad[nodeField]).as("metadata cannot count a truncated node run").isEqualTo(200);
					metadataCalls[0]++;
					return 2L * NEIGHBORS_PER_PREDICATE;
				})) {
			if (boundary.equals("lower")) {
				assertThat(cursor.seekTo(new long[] { 100, 20,
						FIRST_NEIGHBOR + NEIGHBORS_PER_PREDICATE / 2, 0 })).isTrue();
			} else {
				cursor.stopBefore(new long[] { 100, 21,
						FIRST_NEIGHBOR + NEIGHBORS_PER_PREDICATE / 2, 0 });
			}
			List<Group> actual = new ArrayList<>();
			while (cursor.next()) {
				actual.add(new Group(cursor.prefixValue(nodeField), cursor.runRowCount()));
			}
			if (boundary.equals("lower")) {
				assertThat(actual).containsExactly(new Group(100, partialRows),
						new Group(200, 2L * NEIGHBORS_PER_PREDICATE));
				assertThat(metadataCalls[0]).isEqualTo(1);
			} else {
				assertThat(actual).containsExactly(new Group(100, partialRows));
				assertThat(metadataCalls[0]).isZero();
			}
		}
		assertAll(
				() -> assertThat(rows.firstRequested)
						.as("only a run representative is prefetched before deciding its count")
						.isEqualTo(1),
				() -> assertThat(rows.maximumRequested).as("partial counting retains the existing 128-row batches")
						.isEqualTo(128),
				() -> assertThat(rows.fills)
						.as("768 partial members require bounded batches instead of one lock per member")
						.isLessThanOrEqualTo(8),
				() -> assertThat(rows.returned).as("bulk lookahead remains bounded by one batch")
						.isBetween((long) partialRows, partialRows + 128L));
	}

	/** A partial-run batch may contain several subsequent complete runs and even exhaust its delegate. */
	@ParameterizedTest
	@ValueSource(strings = { "spoc", "opsc" })
	void metadataSkippingPreservesAllSuccessorRunsAlreadyPrefetchedByPartialCounting(String order) throws Exception {
		int nodeField = order.charAt(0) == 's' ? TripleIndex.SUBJ_IDX : TripleIndex.OBJ_IDX;
		TripleIndex index = new TripleIndex(order, order, false, 0, 0, (txn, name, flags) -> -1);
		LmdbPrefixRunPlan plan = new LmdbPrefixRunPlan(index, new int[] { nodeField }, 1);
		List<long[]> data = new ArrayList<>();
		for (int ordinal = 0; ordinal < 260; ordinal++) {
			data.add(quad(order, 100, 20, FIRST_NEIGHBOR + ordinal));
		}
		List<Group> expected = new ArrayList<>();
		expected.add(new Group(100, 4));
		for (long node = 200; node < 210; node++) {
			expected.add(new Group(node, 3));
			for (int ordinal = 0; ordinal < 3; ordinal++) {
				data.add(quad(order, node, 20, FIRST_NEIGHBOR + ordinal));
			}
		}
		CountingRows rows = new CountingRows(order, data.toArray(long[][]::new));
		long[] metadataCalls = { 0 };
		try (LmdbPrefixRunCursor cursor = new LmdbPrefixRunIterator(plan, rows, -1, -1, -1, -1, true,
				quad -> {
					assertThat(quad[nodeField]).isBetween(200L, 209L);
					metadataCalls[0]++;
					return 3;
				})) {
			assertThat(cursor.seekTo(new long[] { 100, 20, FIRST_NEIGHBOR + 256, 0 })).isTrue();
			List<Group> actual = new ArrayList<>();
			while (cursor.next()) {
				actual.add(new Group(cursor.prefixValue(nodeField), cursor.runRowCount()));
			}
			assertThat(actual).containsExactlyElementsOf(expected);
			assertThat(metadataCalls[0]).isEqualTo(10);
		}
	}

	private static long[] quad(String order, long node, long predicate, long neighbor) {
		return order.charAt(0) == 'o' ? new long[] { neighbor, predicate, node, 0 }
				: new long[] { node, predicate, neighbor, 0 };
	}

	private record Group(long node, long count) {
	}

	private static final class CountingRows implements RecordIterator {
		private final String order;
		private final long[][] rows;
		private int position;
		private boolean closed;
		long returned;
		int fills;
		int firstRequested;
		int maximumRequested;

		CountingRows(String order) {
			this(order, fullRows(order));
		}

		CountingRows(String order, long[][] rows) {
			this.order = order;
			this.rows = rows;
		}

		private static long[][] fullRows(String order) {
			long[][] rows = new long[4 * NEIGHBORS_PER_PREDICATE][];
			int offset = 0;
			for (long node : new long[] { 100, 200 }) {
				for (long predicate : new long[] { 20, 21 }) {
					for (int ordinal = 0; ordinal < NEIGHBORS_PER_PREDICATE; ordinal++) {
						long neighbor = FIRST_NEIGHBOR + ordinal;
						rows[offset++] = quad(order, node, predicate, neighbor);
					}
				}
			}
			return rows;
		}

		@Override
		public long[] next() {
			if (closed || position == rows.length) {
				closed = true;
				return null;
			}
			returned++;
			return rows[position++];
		}

		@Override
		public int fill(long[] buffer, int maxRows) {
			if (fills++ == 0) {
				firstRequested = maxRows;
			}
			maximumRequested = Math.max(maximumRequested, maxRows);
			return RecordIterator.super.fill(buffer, maxRows);
		}

		@Override
		public boolean seekForward(long subject, long predicate, long object, long context) {
			if (closed) {
				return false;
			}
			long[] target = { subject, predicate, object, context };
			while (position < rows.length && compare(rows[position], target) < 0) {
				position++;
			}
			return true;
		}

		private int compare(long[] left, long[] right) {
			for (char field : order.toCharArray()) {
				int component = switch (field) {
				case 's' -> TripleIndex.SUBJ_IDX;
				case 'p' -> TripleIndex.PRED_IDX;
				case 'o' -> TripleIndex.OBJ_IDX;
				case 'c' -> TripleIndex.CONTEXT_IDX;
				default -> throw new AssertionError(field);
				};
				int comparison = Long.compareUnsigned(left[component], right[component]);
				if (comparison != 0) {
					return comparison;
				}
			}
			return 0;
		}

		@Override
		public long getSourceRowsScannedActual() {
			return returned;
		}

		@Override
		public long getSourceRowsMatchedActual() {
			return returned;
		}

		@Override
		public long getSourceRowsFilteredActual() {
			return 0;
		}

		@Override
		public void close() {
			closed = true;
		}
	}
}
